            text-align: center;
            margin-bottom: 30px;
        }

        .button {
            display: inline-block;
            background-color: #2E604A;
            color: white;
            text-decoration: none;
            padding: 12px 20px;
            border-radius: 4px;
            font-weight: 500;
            text-transform: uppercase;
            font-size: 14px;
        }

        .link-text {
            font-size: 16px;
            color: #333333;
            margin-bottom: 15px;
        }

        .verification-link {
            color: #2932CE;
            text-decoration: none;
            word-break: break-all;
            font-size: 14px;
        }

        .link-container {
            margin-bottom: 30px;
        }

        .disclaimer {
            font-size: 14px;
            font-weight: 500;
            color: #5A5858;
            margin-bottom: 30px;
            padding-top: 20px;
        }

        .signature {
            font-size: 14px;
            color: #777777;
            margin-bottom: 5px;
        }

        .team {
            font-size: 14px;
            color: #777777;
            margin-top: 0;
            font-weight: 600;
        }
    </style>
